function getComboboxYear(n, t) {
    var r = (new Date).getFullYear(), u = "", i;
    for (t.all && (u = "<option value='' id='all' selected='selected'>---Năm---<\/option>"), i = r - 70; i <= r; i++) u += "<option " + (i == r ? "style='font-weight:bold;'" : "") + " value='" + i + "'>" + i + "<\/option>";
    $(n).html(u);
    $(n).val(r)
}

function getComboboxMonth(n, t) {
    var r = (new Date).getMonth() + 1, u, i;
    for (r = r < 10 ? "0" + r : r, u = "", t.all && (u = "<option value='' id='all' selected='selected'>--Tháng--<\/option>"), i = 1; i <= 12; i++) u += "<option " + (i == r ? "style='font-weight:bold;'" : "") + "value='" + (i < 10 ? "0" + i : i) + "'>" + (i < 10 ? "0" + i : i) + "<\/option>";
    $(n).html(u);
    $(n).val(r)
}

function getComboboxDay(n, t) {
    var r = (new Date).getDate(), f, e, u, i;
    for (t.date && (r = parseInt(t.date)), f = "", t.all && (f = "<option value='' id='all' selected='selected'>--Ngày--<\/option>"), e = "", u = new Date(t.year, t.month, 1), u.setDate(u.getDate() - 1), r >= u.getDate() && (r = u.getDate()), r = parseInt(r) < 10 ? "0" + r : r, i = 1; i <= u.getDate(); i++) f += "<option " + (i == r ? "style='font-weight:bold;'" : "") + " value='" + (i < 10 ? "0" + i : i) + "' " + e + ">" + (i < 10 ? "0" + i : i) + "<\/option>";
    $(n).html("");
    $(n).html(f);
    $(n).val(r)
}

var Year = {
    init: function () {
        Year.LoadYear(".cbYear")
    }, LoadYear: function (n) {
        getComboboxYear($(n), {all: !1})
    }
}, Month = {
    init: function () {
        Month.LoadMonth(".cbMonth")
    }, LoadMonth: function (n) {
        getComboboxMonth($(n), {all: !1})
    }
}, Day = {
    init: function () {
        Day.LoadDay("#ddlDay");
        Day.LoadDay("#ddlDay_IDNo")
    }, LoadDay: function (n) {
        var t = new Date;
        getComboboxDay($(n), {year: t.getFullYear(), month: t.getMonth() + 1, all: !1});
        Day.Event(n)
    }, Event: function (n) {
        var t = $(n), r = "." + t.attr("relation"), i = $(r, t.parent());
        if (i) i.off("change").on("change", function () {
            var n = t.val();
            getComboboxDay(t, {year: $($(".cbYear"), t.parent()).val(), month: i.val(), date: n, all: !0})
        })
    }
};
Month.init();
Year.init();
Day.init();